<div class="pharmacy-dashboard-columns">
<?php foreach([['Order analytics',$orders['statuses'],'Completion rate '.$orders['completion_rate'].'% · Cancellation rate '.$orders['cancellation_rate'].'%'],['Prescription review analytics',$prescriptions['statuses'],'Average review time: '.($prescriptions['average_review_hours']===null?'Not available':$prescriptions['average_review_hours'].' hours')],['Payment analytics',$payments['statuses'],'Paid '.$money($payments['paid_amount']).' · Pending '.$money($payments['pending_amount']).' · Refunded '.$money($payments['refunded_amount']).' · Manual reconciliations '.$payments['manual_reconciliations']],['Delivery analytics',$delivery['statuses'],'Completion rate '.$delivery['completion_rate'].'% · Average fulfilment time '.($delivery['average_fulfilment_hours']===null?'Not available':$delivery['average_fulfilment_hours'].' hours')]] as [$title,$items,$note]): ?><section class="card pharmacy-dashboard-panel"><h2><?= esc($title) ?></h2><div class="pharmacy-status-summary"><?php foreach($items as $name=>$count): ?><div><span><?= esc($statusLabel($name)) ?></span><strong><?= number_format((float)$count) ?></strong></div><?php endforeach; ?></div><p class="pharmacy-dashboard-note"><?= esc($note) ?></p></section><?php endforeach; ?><section class="card pharmacy-dashboard-panel"><h2>Central stock analytics</h2><div class="pharmacy-status-summary"><?php foreach(['active_medicines'=>'Active medicines','available_batches'=>'Available batches','low_stock_medicines'=>'Low-stock medicines','near_expiry_batches'=>'Near-expiry batches','expired_inactive'=>'Expired / inactive','out_of_stock_medicines'=>'Out of stock'] as $key=>$title): ?><div><span><?= esc($title) ?></span><strong><?= number_format((float)$stock[$key]) ?></strong></div><?php endforeach; ?></div><p class="pharmacy-dashboard-note">Top medicines by order quantity: <?php foreach($stock['top_medicines'] as $medicine): ?><?= esc($medicine['medicine_name']) ?> (<?= (int)$medicine['quantity'] ?>)<?php endforeach; ?></p></section>
</div>
<?php foreach([['Latest orders',$latest['orders'],['Order number','order_number','Patient','patient_name','Order date','created_at_display','Order status','status','Payment status','payment_status','Delivery status','delivery_status','Amount','total'],'pharmacy/orders'],['Latest prescription reviews',$latest['prescriptions'],['Prescription','prescription_number','Patient','patient_name','Prescription date','prescription_date_display','Doctor','doctor_name','Medicine count','medicine_count','Review status','status','Review date','updated_at_display'],'pharmacy/prescriptions'],['Latest payments',$latest['payments'],['Invoice','invoice_number','Order','order_number','Patient','patient_name','Amount','total','Provider','provider_name','Payment status','payment_status','Reference','payment_reference'],'pharmacy/billing'],['Latest deliveries',$latest['deliveries'],['Order','order_number','Patient','patient_name','Provider','delivery_provider_name_snapshot','Tracking','tracking_reference','Delivery status','delivery_status','Dispatched','dispatched_at_display','Delivered','delivered_at_display'],'pharmacy/delivery']] as [$title,$rows,$columns,$url]): ?><section class="card pharmacy-dashboard-list" aria-label="<?= esc($title) ?>"><div class="pharmacy-dashboard-panel-head"><h2><?= esc($title) ?></h2><a href="<?= base_url($url) ?>">View all</a></div><?php if(!$rows): ?><p class="pharmacy-dashboard-empty">No records in the selected range.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><?php for($i=0;$i<count($columns);$i+=2): ?><th><?= esc($columns[$i]) ?></th><?php endfor; ?><th>Action</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php for($i=1;$i<count($columns);$i+=2): ?><?php $field=$columns[$i];$value=$row[$field]??''; ?><td data-label="<?= esc($columns[$i-1]) ?>"><?php if(in_array($field,['status','payment_status','delivery_status'],true)): ?><span class="badge pharmacy-status-<?= esc(strtolower((string)$value),'attr') ?>"><?= esc($statusLabel($value)) ?></span><?php elseif($field==='total'): ?><?= esc($money($value)) ?><?php else: ?><?= esc($value!==''?$value:'Not recorded') ?><?php endif; ?></td><?php endfor; ?><td><a class="btn btn-sm btn-outline-primary" href="<?= base_url($url) ?>">View</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endforeach; ?>
<section class="card pharmacy-dashboard-list" aria-label="Stock alerts"><div class="pharmacy-dashboard-panel-head"><h2>Stock alerts</h2><a href="<?= base_url('pharmacy/inventory') ?>">View stock</a></div><?php if(!$latest['stock_alerts']): ?><p class="pharmacy-dashboard-empty">No stock alerts.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Medicine</th><th>Batch</th><th>Quantity</th><th>Expiry</th><th>Status</th></tr></thead><tbody><?php foreach($latest['stock_alerts'] as $row): ?><tr><td><?= esc($row['medicine_name']) ?></td><td><?= esc($row['batch_number']) ?></td><td><?= (int)$row['quantity_available'] ?></td><td><?= esc((new DateTimeImmutable($row['expiry_date']))->format('d-m-Y')) ?></td><td><span class="badge pharmacy-status-<?= esc(strtolower((string)$row['status']),'attr') ?>"><?= esc($statusLabel($row['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</main>
